39	pub struct Qwen3MemoryOptions {
40	    /// Mirrors vLLM's `gpu_memory_utilization`: the KV pool gets what remains
41	    /// inside this requested budget after weights, profiled non-KV runtime
42	    /// memory, and a small safety margin are accounted for.
43	    gpu_memory_utilization: f64,
44	    /// Extra bytes held back after the profile result to cover allocator
45	    /// fragmentation and small unprofiled runtime drift.
46	    pub(crate) kv_cache_memory_margin_bytes: usize,
47	    /// KV cache page (block) size in tokens (`--kv-page-size`). FlashInfer
48	    /// constrains this to [`VALID_KV_PAGE_SIZES`]; 16 by default.
49	    pub(crate) page_size: usize,
50	}
