52	impl Qwen3MemoryOptions {
53	    pub const fn new(
54	        gpu_memory_utilization: f64,
55	        kv_cache_memory_margin_bytes: usize,
56	        page_size: usize,
57	    ) -> Self {
58	        Self {
59	            gpu_memory_utilization,
60	            kv_cache_memory_margin_bytes,
61	            page_size,
62	        }
63	    }
64	
65	    pub fn validate(self) -> Result<Self> {
66	        anyhow::ensure!(
67	            self.gpu_memory_utilization > 0.0 && self.gpu_memory_utilization <= 1.0,
68	            "gpu_memory_utilization must be in (0, 1], got {}",
69	            self.gpu_memory_utilization
70	        );
71	        anyhow::ensure!(
72	            VALID_KV_PAGE_SIZES.contains(&self.page_size),
73	            "page_size must be one of {:?}, got {}",
74	            VALID_KV_PAGE_SIZES,
75	            self.page_size
76	        );
77	        Ok(self)
78	    }
79	}
