286	impl PackedLoraRegistry {
287	    fn empty(max_loras: usize, num_layers: usize) -> Self {
288	        Self {
289	            slots_by_name: HashMap::new(),
290	            slot_names: vec![None; max_loras],
291	            packed_layers: (0..num_layers).map(|_| PackedLoraLayer::empty()).collect(),
292	        }
293	    }
294	
295	    fn slot_for(&self, name: &str) -> Option<usize> {
296	        self.slots_by_name.get(name).copied()
297	    }
298	
299	    fn layer(&self, layer_idx: usize) -> Option<&PackedLoraLayer> {
300	        self.packed_layers.get(layer_idx)
301	    }
302	
303	    fn slot_for_install(&self, name: &str, load_inplace: bool) -> Result<usize> {
304	        if let Some(slot) = self.slot_for(name) {
305	            anyhow::ensure!(load_inplace, "Qwen3 LoRA adapter {name} is already loaded");
306	            return Ok(slot);
307	        }
308	        self.slot_names
309	            .iter()
310	            .position(Option::is_none)
311	            .ok_or_else(|| anyhow::anyhow!("Qwen3 LoRA adapter capacity exceeded"))
312	    }
313	
314	    fn bind_slot(&mut self, slot: usize, name: &str) {
315	        if let Some(previous_name) = self.slot_names[slot].replace(name.to_string()) {
316	            self.slots_by_name.remove(&previous_name);
317	        }
318	        self.slots_by_name.insert(name.to_string(), slot);
319	    }
320	
321	    fn release_slot(&mut self, name: &str) -> Result<usize> {
322	        let slot = self
323	            .slots_by_name
324	            .remove(name)
325	            .ok_or_else(|| anyhow::anyhow!("Qwen3 LoRA adapter {name} is not loaded"))?;
326	        self.slot_names[slot] = None;
327	        Ok(slot)
328	    }
329	}
