422	    /// Whether decode steps replay pre-captured graphs that record NCCL
423	    /// collectives — i.e. CUDA Graph on a tensor-parallel model.
424	    pub(crate) fn tp_graph_enabled(&self) -> bool {
425	        self.enable_cuda_graph && self.tp_comm.is_some()
426	    }
427	
428	    /// Force NCCL connect before any capture records a collective (lazy connect
429	    /// inside `cuStreamBeginCapture` is the classic hazard). NCCL >= 2.22
430	    /// connects per size-selected algorithm, so warm one all-reduce at every
431	    /// bucket's message size. No-op without a TP communicator.
432	    pub(crate) fn warmup_tp_collective(&self) -> Result<()> {
433	        if let Some(comm) = &self.tp_comm {
434	            let buckets = crate::batch_decode_buffers::BATCH_BUCKETS;
435	            let max_elems = buckets.last().unwrap() * self.config.hidden_size;
436	            let mut scratch = self.ctx.stream.alloc_zeros::<bf16>(max_elems)?;
437	            for &bucket in buckets {
438	                let mut view = scratch.slice_mut(0..bucket * self.config.hidden_size);
439	                comm.all_reduce_in_place(&mut view, &ReduceOp::Sum)
440	                    .map_err(|e| anyhow::anyhow!("nccl warm-up all-reduce failed: {e:?}"))?;
441	            }
442	            self.ctx.stream.synchronize()?;
443	        }
444	        Ok(())
445	    }
