552	    pub(crate) fn decode_lora_slots(&self, adapters: &[Option<&str>]) -> Result<Option<Vec<i32>>> {
553	        let mut slots = Vec::with_capacity(adapters.len());
554	        let mut any_lora = false;
555	        for adapter in adapters {
556	            match adapter {
557	                Some(name) => {
558	                    let Some(slot) = self.packed_lora.slot_for(name) else {
559	                        anyhow::bail!("Qwen3 LoRA adapter {name} is not loaded");
560	                    };
561	                    slots.push(slot as i32);
562	                    any_lora = true;
563	                }
564	                None => slots.push(-1),
565	            }
566	        }
567	        Ok(any_lora.then_some(slots))
568	    }
