619	    fn pack_lora_projection_slot(
620	        &mut self,
621	        slot: usize,
622	        projection: &DeviceLoraProjection,
623	        scale: f32,
624	        layer_idx: usize,
625	        kind: LoraProjectionKind,
626	    ) -> Result<()> {
627	        let max_loras = self.max_loras;
628	        let max_rank = self.max_lora_rank;
629	        let packed_slot = &mut self.packed_lora.packed_layers[layer_idx].projections[kind.index()];
630	        if packed_slot.is_none() {
631	            *packed_slot = Some(PackedLoraProjection::new(
632	                &self.ctx,
633	                max_loras,
634	                max_rank,
635	                projection.a.cols,
636	                projection.b.rows,
637	            )?);
638	        }
639	        let packed = packed_slot
640	            .as_mut()
641	            .expect("packed LoRA projection was initialized");
642	        packed.write_slot(&self.ctx, slot, projection, scale)
643	    }
