692	    pub(crate) fn profiled_kv_budget(
693	        &self,
694	        max_prefill_tokens: usize,
695	        max_decode_batch_size: usize,
696	        dflash_kv_bytes_per_token: usize,
697	        memory_options: Qwen3MemoryOptions,
698	    ) -> Result<KvBudget> {
699	        let memory_options = memory_options.validate()?;
700	        let geometry = self.kv_budget_geometry(memory_options.page_size);
701	        let bytes_per_block = Self::kv_bytes_per_block(&geometry)?;
702	        let (initial_free_bytes, total_bytes) = mem_info_bytes()?;
703	        let requested_bytes =
704	            (total_bytes as f64 * memory_options.gpu_memory_utilization).ceil() as usize;
705	        let initial_used_bytes = total_bytes.saturating_sub(initial_free_bytes);
706	        anyhow::ensure!(
707	            initial_used_bytes < requested_bytes,
708	            "Qwen3 requested GPU memory is already exhausted before KV allocation: \
709	             used={} MiB, requested={} MiB (utilization {:.2})",
710	            initial_used_bytes / (1024 * 1024),
711	            requested_bytes / (1024 * 1024),
712	            memory_options.gpu_memory_utilization
713	        );
714	
715	        anyhow::ensure!(
716	            max_prefill_tokens > 0,
717	            "Qwen3 memory profile requires positive max_prefill_tokens"
718	        );
719	        let profile_prefill_rows = 1;
720	        let profile_decode_rows = max_decode_batch_size.saturating_sub(profile_prefill_rows);
721	        anyhow::ensure!(
722	            profile_decode_rows > 0,
723	            "Qwen3 memory profile requires decode capacity above prefill rows"
724	        );
725	        let profile_rows = profile_prefill_rows + profile_decode_rows;
726	        let profile_blocks =
727	            profile_temp_blocks(max_prefill_tokens, profile_decode_rows, geometry.block_size);
728	        let profile_kv_bytes = crate::sizing::product(&[profile_blocks, bytes_per_block])?;
729	        let mut peak_used_bytes = initial_used_bytes;
730	        let mut record_peak = || -> Result<()> {
731	            let (free_bytes, total_bytes) = mem_info_bytes()?;
732	            peak_used_bytes = peak_used_bytes.max(total_bytes.saturating_sub(free_bytes));
733	            Ok(())
734	        };
735	
736	        let profile_kv = KvBuffer::new(
737	            &self.ctx.stream,
738	            geometry.num_layers,
739	            geometry.num_kv_heads,
740	            geometry.head_dim,
741	            geometry.block_size,
742	            profile_blocks,
743	        )
744	        .context("Qwen3 memory profile temp KV alloc failed")?;
745	        record_peak()?;
746	
747	        let mut decode_bufs = BatchDecodeBuffers::new(
748	            self.device_ctx(),
749	            self.config.hidden_size,
750	            self.local_q_dim(),
751	            self.local_kv_dim(),
752	            self.local_intermediate_size(),
753	            self.config.logits_rows,
754	            max_decode_batch_size,
755	            geometry.block_size,
756	            0,
757	            self.local_num_attention_heads(),
758	            self.config.max_position_embeddings,
759	            self.fused_decode_qkv(),
760	        )
761	        .context("Qwen3 memory profile decode buffer alloc failed")?;
762	        record_peak()?;
763	
764	        let mut sample_scratch = pegainfer_sample::SampleScratch::new(
765	            self.device_ctx(),
766	            self.config.logits_rows,
767	            profile_rows,
768	        )
769	        .context("Qwen3 memory profile sampling scratch alloc failed")?;
770	        record_peak()?;
771	
772	        self.profile_unified_step_memory(
773	            max_prefill_tokens,
774	            profile_decode_rows,
775	            &profile_kv,
776	            &mut decode_bufs,
777	            &mut sample_scratch,
778	            &mut record_peak,
779	        )?;
780	        record_peak()?;
781	
782	        // `peak_used_bytes` includes the temporary KV buffer used only to make
783	        // the dummy step legal. The final KV pool is sized separately below, so
784	        // remove that profile-only backing store from the measured non-KV peak.
785	        let profile_peak_increase = peak_used_bytes.saturating_sub(initial_used_bytes);
786	        let non_kv_peak_increase = profile_peak_increase.saturating_sub(profile_kv_bytes);
787	        let non_kv_bytes = initial_used_bytes
788	            .saturating_add(non_kv_peak_increase)
789	            .saturating_add(memory_options.kv_cache_memory_margin_bytes);
790	        anyhow::ensure!(
791	            requested_bytes > non_kv_bytes,
792	            "Qwen3 memory profile leaves no room for KV cache: requested={} MiB, \
793	             non_kv={} MiB, margin={} MiB",
794	            requested_bytes / (1024 * 1024),
795	            non_kv_bytes / (1024 * 1024),
796	            memory_options.kv_cache_memory_margin_bytes / (1024 * 1024)
797	        );
798	        let kv_budget_bytes = requested_bytes - non_kv_bytes;
799	        log::info!(
800	            "memory profile: total={} MiB requested={} MiB ({:.0}%) initial_used={} MiB \
801	             peak_non_kv_increase={} MiB margin={} MiB -> KV budget={} MiB",
802	            total_bytes / (1024 * 1024),
803	            requested_bytes / (1024 * 1024),
804	            memory_options.gpu_memory_utilization * 100.0,
805	            initial_used_bytes / (1024 * 1024),
806	            non_kv_peak_increase / (1024 * 1024),
807	            memory_options.kv_cache_memory_margin_bytes / (1024 * 1024),
808	            kv_budget_bytes / (1024 * 1024),
809	        );
810	        Self::kv_budget_from_bytes(
811	            geometry,
812	            bytes_per_block,
813	            dflash_kv_bytes_per_token,
814	            kv_budget_bytes,
815	            initial_free_bytes,
816	            "profiled",
817	        )
818	    }
