1	//! Checkpoint loading for [`Qwen3Model`]: record the whole plan, then upload.
2	
3	use std::collections::HashMap;
4	use std::time::Instant;
5	
6	use anyhow::Result;
7	use log::debug;
8	use log::info;
9	use pegainfer_core::ops;
10	use pegainfer_core::rope::RopeTableSpec;
11	use pegainfer_core::rope::precompute_rope;
12	use pegainfer_core::tensor::DeviceContext;
13	use pegainfer_core::weight_loader::FusedPart;
14	use pegainfer_core::weight_loader::SlotId;
15	use pegainfer_core::weight_loader::StagedWeightLoader;
16	use pegainfer_core::weight_loader::VecSlotId;
17	use pegainfer_core::weight_loader::WeightPrefetch;
18	use pegainfer_core::weight_loader::deserialize_shards;
19	use pegainfer_core::weight_loader::load_shard_info;
20	use pegainfer_core::weight_loader::mmap_shards;
21	
22	use super::Attention;
23	use super::MLP;
24	use super::PackedLoraRegistry;
25	use super::Qwen3Model;
26	use super::TransformerBlock;
27	use crate::config::Config;
28	use crate::config::TensorParallelConfig;
29	use crate::projection_fusion::select_decode_projection_path;
30	
31	#[derive(Clone, Copy, Debug)]
32	pub(crate) struct ModelRuntimeConfig {
33	    pub(crate) enable_cuda_graph: bool,
34	    pub(crate) tensor_parallel: Option<TensorParallelConfig>,
35	    pub(crate) device_ordinal: usize,
36	    pub(crate) max_loras: usize,
37	    pub(crate) max_lora_rank: usize,
38	    pub(crate) decode_overlap: crate::DecodeOverlap,
39	    pub(crate) dflash_enabled: bool,
40	}
41	
42	impl Default for ModelRuntimeConfig {
43	    fn default() -> Self {
44	        Self {
45	            enable_cuda_graph: true,
46	            tensor_parallel: None,
47	            device_ordinal: 0,
48	            max_loras: crate::Qwen3LoraOptions::DEFAULT_MAX_LORAS,
49	            max_lora_rank: crate::Qwen3LoraOptions::DEFAULT_MAX_LORA_RANK,
50	            decode_overlap: crate::DecodeOverlap::Off,
51	            dflash_enabled: false,
52	        }
53	    }
54	}
55	
56	struct LayerSlots {
57	    input_layernorm: VecSlotId,
58	    qkv: SlotId,
59	    o: SlotId,
60	    q_norm: VecSlotId,
61	    k_norm: VecSlotId,
62	    post_attention_layernorm: VecSlotId,
63	    gate_up: SlotId,
64	    down: SlotId,
65	}
66	
67	impl Qwen3Model {
68	    pub(crate) fn from_safetensors_with_runtime(
69	        model_path: &str,
70	        runtime: ModelRuntimeConfig,
71	    ) -> Result<Self> {
72	        info!("Loading model from: {}", model_path);
73	        debug!("Initializing GPU device {}", runtime.device_ordinal);
74	        let ctx = DeviceContext::new_with_device(runtime.device_ordinal)?;
75	
76	        let mut config = Config::from_file(model_path)?;
77	        let effective_vocab = pegainfer_core::decodable_vocab::decodable_vocab_width(model_path)?;
78	        anyhow::ensure!(
79	            effective_vocab <= config.vocab_size,
80	            "tokenizer defines ids up to {} but checkpoint vocab_size is {}",
81	            effective_vocab - 1,
82	            config.vocab_size
83	        );
84	        config.decodable_vocab = effective_vocab;
85	        config.logits_rows = pegainfer_core::decodable_vocab::aligned_logits_rows(
86	            effective_vocab,
87	            config.vocab_size,
88	        );
89	        if config.decodable_vocab < config.vocab_size {
90	            info!(
91	                "output projection: selection bounded to decodable vocab {}, projecting {} aligned rows (checkpoint pads to {})",
92	                config.decodable_vocab, config.logits_rows, config.vocab_size
93	            );
94	        }
95	        let tail_ids = (config.decodable_vocab..config.logits_rows)
96	            .map(u32::try_from)
97	            .collect::<std::result::Result<Vec<_>, _>>()?;
98	        let logits_tail_suppress = (!tail_ids.is_empty())
99	            .then(|| ops::SuppressIds::upload(&ctx, &tail_ids, config.logits_rows))
100	            .transpose()?;
101	        let tensor_parallel = runtime.tensor_parallel.unwrap_or_default();
102	        tensor_parallel.validate_for(&config)?;
103	        let (cc_major, cc_minor) = ctx.ctx.compute_capability()?;
104	        let device_sm = cc_major * 10 + cc_minor;
105	        let q_dim = config.local_q_dim(tensor_parallel);
106	        let kv_dim = config.local_kv_dim(tensor_parallel);
107	        let (decode_projection_path, decode_projection_reason) = select_decode_projection_path(
108	            tensor_parallel,
109	            pegainfer_kernels::ops::numeric_policy(),
110	            runtime.decode_overlap,
111	            runtime.dflash_enabled,
112	            device_sm,
113	            config.hidden_size,
114	            q_dim,
115	            kv_dim,
116	            config.num_hidden_layers,
117	        );
118	        if tensor_parallel.rank == 0 {
119	            info!(
120	                "decode projection path: resolved={decode_projection_path:?}, \
121	                 reason={decode_projection_reason}, sm={device_sm}, hidden={}, q_dim={q_dim}, \
122	                 kv_dim={kv_dim}, layers={}",
123	                config.hidden_size, config.num_hidden_layers
124	            );
125	        }
126	
127	        let (shard_paths, weight_map) = load_shard_info(model_path)?;
128	        debug!("Loading {} safetensor shard(s)", shard_paths.len());
129	        let prefetch =
130	            (tensor_parallel.world_size == 1).then(|| WeightPrefetch::spawn(&shard_paths));
131	        let mmaps = mmap_shards(&shard_paths)?;
132	        let shards = deserialize_shards(&mmaps)?;
133	
134	        let t_gpu = Instant::now();
135	        let mut loader = StagedWeightLoader::new(&ctx, &shards, &weight_map)?;
136	        let hidden = config.hidden_size;
137	        debug!("Loading embeddings to GPU");
138	        let embed_slot = loader.matrix("model.embed_tokens.weight", config.vocab_size, hidden)?;
139	        let lm_head_slot = if config.tie_word_embeddings {
140	            debug!("Using tied input/output embeddings");
141	            None
142	        } else {
143	            debug!("Loading untied LM head to GPU");
144	            Some(loader.matrix(config.lm_head_tensor_name(), config.vocab_size, hidden)?)
145	        };
146	
147	        debug!(
148	            "Loading layers to GPU: num_layers={}, tp_rank={}, tp_world_size={}",
149	            config.num_hidden_layers, tensor_parallel.rank, tensor_parallel.world_size,
150	        );
151	        let mut layer_slots = Vec::with_capacity(config.num_hidden_layers);
152	        let q_total = config.num_attention_heads * config.head_dim;
153	        let kv_total = config.num_key_value_heads * config.head_dim;
154	        let inter_total = config.intermediate_size;
155	        let (q_row_offset, q_rows) = tensor_parallel.shard_range(q_total);
156	        let (kv_row_offset, kv_rows) = tensor_parallel.shard_range(kv_total);
157	        let (inter_row_offset, inter_rows) = tensor_parallel.shard_range(inter_total);
158	        for i in 0..config.num_hidden_layers {
159	            let prefix = format!("model.layers.{}", i);
160	
161	            // shard_range covers world_size == 1 too (offset 0, full rows), so
162	            // one fused load serves both the sharded and unsharded paths.
163	            let q_name = format!("{prefix}.self_attn.q_proj.weight");
164	            let k_name = format!("{prefix}.self_attn.k_proj.weight");
165	            let v_name = format!("{prefix}.self_attn.v_proj.weight");
166	            let qkv_proj = loader.fused_rows(
167	                hidden,
168	                &[
169	                    FusedPart {
170	                        name: &q_name,
171	                        src_rows: q_total,
172	                        row_offset: q_row_offset,
173	                        rows: q_rows,
174	                    },
175	                    FusedPart {
176	                        name: &k_name,
177	                        src_rows: kv_total,
178	                        row_offset: kv_row_offset,
179	                        rows: kv_rows,
180	                    },
181	                    FusedPart {
182	                        name: &v_name,
183	                        src_rows: kv_total,
184	                        row_offset: kv_row_offset,
185	                        rows: kv_rows,
186	                    },
187	                ],
188	            )?;
