//! Checkpoint loading for [`Qwen3Model`]: record the whole plan, then upload.

use std::collections::HashMap;
use std::time::Instant;

use anyhow::Result;
use log::debug;
use log::info;
use pegainfer_core::ops;
use pegainfer_core::rope::RopeTableSpec;
use pegainfer_core::rope::precompute_rope;
use pegainfer_core::tensor::DeviceContext;
use pegainfer_core::weight_loader::FusedPart;
use pegainfer_core::weight_loader::SlotId;
use pegainfer_core::weight_loader::StagedWeightLoader;
use pegainfer_core::weight_loader::VecSlotId;
use pegainfer_core::weight_loader::WeightPrefetch;
use pegainfer_core::weight_loader::deserialize_shards;
use pegainfer_core::weight_loader::load_shard_info;
use pegainfer_core::weight_loader::mmap_shards;

use super::Attention;
use super::MLP;
use super::PackedLoraRegistry;
use super::Qwen3Model;
use super::TransformerBlock;
use crate::config::Config;
use crate::config::TensorParallelConfig;
use crate::projection_fusion::select_decode_projection_path;

#[derive(Clone, Copy, Debug)]
pub(crate) struct ModelRuntimeConfig {
    pub(crate) enable_cuda_graph: bool,
    pub(crate) tensor_parallel: Option<TensorParallelConfig>,
    pub(crate) device_ordinal: usize,
    pub(crate) max_loras: usize,
    pub(crate) max_lora_rank: usize,
    pub(crate) decode_overlap: crate::DecodeOverlap,
    pub(crate) dflash_enabled: bool,
}

impl Default for ModelRuntimeConfig {
    fn default() -> Self {
        Self {
            enable_cuda_graph: true,
            tensor_parallel: None,
            device_ordinal: 0,
            max_loras: crate::Qwen3LoraOptions::DEFAULT_MAX_LORAS,
            max_lora_rank: crate::Qwen3LoraOptions::DEFAULT_MAX_LORA_RANK,
            decode_overlap: crate::DecodeOverlap::Off,
            dflash_enabled: false,
        }
    }
}

struct LayerSlots {
    input_layernorm: VecSlotId,
    qkv: SlotId,
    o: SlotId,
    q_norm: VecSlotId,
    k_norm: VecSlotId,
    post_attention_layernorm: VecSlotId,
    gate_up: SlotId,
    down: SlotId,
}

impl Qwen3Model {
    pub(crate) fn from_safetensors_with_runtime(
        model_path: &str,
        runtime: ModelRuntimeConfig,
    ) -> Result<Self> {
        info!("Loading model from: {}", model_path);
        debug!("Initializing GPU device {}", runtime.device_ordinal);
        let ctx = DeviceContext::new_with_device(runtime.device_ordinal)?;

        let mut config = Config::from_file(model_path)?;
        let effective_vocab = pegainfer_core::decodable_vocab::decodable_vocab_width(model_path)?;
        anyhow::ensure!(
            effective_vocab <= config.vocab_size,
            "tokenizer defines ids up to {} but checkpoint vocab_size is {}",
            effective_vocab - 1,
            config.vocab_size
        );
        config.decodable_vocab = effective_vocab;
        config.logits_rows = pegainfer_core::decodable_vocab::aligned_logits_rows(
            effective_vocab,
            config.vocab_size,
        );
        if config.decodable_vocab < config.vocab_size {
            info!(
                "output projection: selection bounded to decodable vocab {}, projecting {} aligned rows (checkpoint pads to {})",
                config.decodable_vocab, config.logits_rows, config.vocab_size
            );
        }
        let tail_ids = (config.decodable_vocab..config.logits_rows)
            .map(u32::try_from)
            .collect::<std::result::Result<Vec<_>, _>>()?;
        let logits_tail_suppress = (!tail_ids.is_empty())
            .then(|| ops::SuppressIds::upload(&ctx, &tail_ids, config.logits_rows))
            .transpose()?;
        let tensor_parallel = runtime.tensor_parallel.unwrap_or_default();
        tensor_parallel.validate_for(&config)?;
        let (cc_major, cc_minor) = ctx.ctx.compute_capability()?;
        let device_sm = cc_major * 10 + cc_minor;
        let q_dim = config.local_q_dim(tensor_parallel);
        let kv_dim = config.local_kv_dim(tensor_parallel);
        let (decode_projection_path, decode_projection_reason) = select_decode_projection_path(
            tensor_parallel,
            pegainfer_kernels::ops::numeric_policy(),
            runtime.decode_overlap,
            runtime.dflash_enabled,
            device_sm,
            config.hidden_size,
            q_dim,
            kv_dim,
            config.num_hidden_layers,
        );
        if tensor_parallel.rank == 0 {
            info!(
                "decode projection path: resolved={decode_projection_path:?}, \
                 reason={decode_projection_reason}, sm={device_sm}, hidden={}, q_dim={q_dim}, \
                 kv_dim={kv_dim}, layers={}",
                config.hidden_size, config.num_hidden_layers
            );
        }

        let (shard_paths, weight_map) = load_shard_info(model_path)?;
        debug!("Loading {} safetensor shard(s)", shard_paths.len());
        let prefetch =
            (tensor_parallel.world_size == 1).then(|| WeightPrefetch::spawn(&shard_paths));
        let mmaps = mmap_shards(&shard_paths)?;
        let shards = deserialize_shards(&mmaps)?;

        let t_gpu = Instant::now();
        let mut loader = StagedWeightLoader::new(&ctx, &shards, &weight_map)?;
        let hidden = config.hidden_size;
        debug!("Loading embeddings to GPU");
        let embed_slot = loader.matrix("model.embed_tokens.weight", config.vocab_size, hidden)?;
        let lm_head_slot = if config.tie_word_embeddings {
            debug!("Using tied input/output embeddings");
            None
        } else {
            debug!("Loading untied LM head to GPU");
            Some(loader.matrix(config.lm_head_tensor_name(), config.vocab_size, hidden)?)
        };

        debug!(
            "Loading layers to GPU: num_layers={}, tp_rank={}, tp_world_size={}",
            config.num_hidden_layers, tensor_parallel.rank, tensor_parallel.world_size,
        );
        let mut layer_slots = Vec::with_capacity(config.num_hidden_layers);
        let q_total = config.num_attention_heads * config.head_dim;
        let kv_total = config.num_key_value_heads * config.head_dim;
        let inter_total = config.intermediate_size;
        let (q_row_offset, q_rows) = tensor_parallel.shard_range(q_total);
        let (kv_row_offset, kv_rows) = tensor_parallel.shard_range(kv_total);
        let (inter_row_offset, inter_rows) = tensor_parallel.shard_range(inter_total);
        for i in 0..config.num_hidden_layers {
            let prefix = format!("model.layers.{}", i);

            // shard_range covers world_size == 1 too (offset 0, full rows), so
            // one fused load serves both the sharded and unsharded paths.
            let q_name = format!("{prefix}.self_attn.q_proj.weight");
            let k_name = format!("{prefix}.self_attn.k_proj.weight");
            let v_name = format!("{prefix}.self_attn.v_proj.weight");
            let qkv_proj = loader.fused_rows(
                hidden,
                &[
                    FusedPart {
                        name: &q_name,
                        src_rows: q_total,
                        row_offset: q_row_offset,
                        rows: q_rows,
                    },
                    FusedPart {
                        name: &k_name,
                        src_rows: kv_total,
                        row_offset: kv_row_offset,
                        rows: kv_rows,
                    },
                    FusedPart {
                        name: &v_name,
                        src_rows: kv_total,
                        row_offset: kv_row_offset,
                        rows: kv_rows,
                    },
                ],
            )?;

            let gate_name = format!("{prefix}.mlp.gate_proj.weight");
            let up_name = format!("{prefix}.mlp.up_proj.weight");
            let gate_up_proj = loader.fused_rows(
                hidden,
                &[
                    FusedPart {
                        name: &gate_name,
                        src_rows: inter_total,
                        row_offset: inter_row_offset,
                        rows: inter_rows,
                    },
                    FusedPart {
                        name: &up_name,
                        src_rows: inter_total,
                        row_offset: inter_row_offset,
                        rows: inter_rows,
                    },
                ],
            )?;

            layer_slots.push(LayerSlots {
                input_layernorm: loader
                    .vector(&format!("{}.input_layernorm.weight", prefix), hidden)?,
                qkv: qkv_proj,
                o: if tensor_parallel.is_sharded() {
                    loader.col_shard(
                        &format!("{}.self_attn.o_proj.weight", prefix),
                        hidden,
                        q_total,
                        q_row_offset,
                        q_rows,
                    )?
                } else {
                    loader.matrix(
                        &format!("{}.self_attn.o_proj.weight", prefix),
                        hidden,
                        q_total,
                    )?
                },
                q_norm: loader.vector(
                    &format!("{}.self_attn.q_norm.weight", prefix),
                    config.head_dim,
                )?,
                k_norm: loader.vector(
                    &format!("{}.self_attn.k_norm.weight", prefix),
                    config.head_dim,
                )?,
                post_attention_layernorm: loader.vector(
                    &format!("{}.post_attention_layernorm.weight", prefix),
                    hidden,
                )?,
                gate_up: gate_up_proj,
                down: if tensor_parallel.is_sharded() {
                    loader.col_shard(
                        &format!("{}.mlp.down_proj.weight", prefix),
                        hidden,
                        inter_total,
                        inter_row_offset,
                        inter_rows,
                    )?
                } else {
                    loader.matrix(
                        &format!("{}.mlp.down_proj.weight", prefix),
                        hidden,
                        inter_total,
                    )?
                },
            });
        }

        let norm_slot = loader.vector("model.norm.weight", hidden)?;

        debug!("Precomputing RoPE cache on GPU");
        let (cos_cache, sin_cache) = precompute_rope(
            &ctx,
            &RopeTableSpec {
                rotary_dim: config.head_dim,
                frequency_dim: config.head_dim,
                max_seq_len: config.max_position_embeddings,
                theta: config.rope_theta,
            },
        )?;

        loader.finish()?;
        let embed_tokens = loader.take(embed_slot);
        let lm_head = lm_head_slot.map(|slot| loader.take(slot));
        let norm = loader.take_vec(norm_slot);
        let layers: Vec<TransformerBlock> = layer_slots
            .into_iter()
            .map(|slots| TransformerBlock {
                input_layernorm: loader.take_vec(slots.input_layernorm),
                attention: Attention {
                    qkv_proj: loader.take(slots.qkv),
                    o_proj: loader.take(slots.o),
                    q_norm: loader.take_vec(slots.q_norm),
                    k_norm: loader.take_vec(slots.k_norm),
                    q_dim: q_rows,
                    kv_dim: kv_rows,
                },
                post_attention_layernorm: loader.take_vec(slots.post_attention_layernorm),
                mlp: MLP {
                    gate_up_proj: loader.take(slots.gate_up),
                    down_proj: loader.take(slots.down),
                },
            })
            .collect();
        drop(loader);
        drop(prefetch);
        info!(
            "GPU model loaded in {:.0}ms",
            t_gpu.elapsed().as_secs_f64() * 1e3
        );
        drop(shards);
        // Page-table teardown of the multi-GB mapping is not worth blocking
        // startup on; nothing references the mmaps once every weight is uploaded.
        std::thread::Builder::new()
            .name("qwen3-weights-unmap".into())
            .spawn(move || drop(mmaps))
            .map_err(|e| anyhow::anyhow!("weight unmap thread spawn failed: {e}"))?;

        let num_hidden_layers = config.num_hidden_layers;
        let model = Self {
            ctx,
            config,
            embed_tokens,
            lm_head,
            logits_tail_suppress,
            layers,
            norm,
            cos_cache,
            sin_cache,

        };
        dag.fused_add_rms_norm(
            label,
            &mut bufs.hidden,
            &bufs.mlp_out,
            next_weight,
            &mut bufs.normed,
        )?;
    }

    // Output projection: logits [logits_rows, bs]
    dag.lm_head(dag_label!("lm_head"), &bufs.normed, &mut bufs.logits)?;

    Ok(())
}

#[allow(clippy::too_many_arguments)]
fn batch_decode_layer(
    &self,
    layer_idx: usize,
    layer: &TransformerBlock,
    dag: &BatchDecodeDag<'_>,
    use_lora: bool,
    bufs: &mut BatchDecodeBuffers,
) -> Result<()> {
    let q_dim = layer.attention.q_dim;
    let kv_dim = layer.attention.kv_dim;
    let fused_qkv = self.fused_decode_qkv();
    if fused_qkv {
        let qkv_out = bufs
            .qkv_out
            .as_mut()
            .expect("fused QKV plan requires qkv_out");
        dag.qkv_proj(
            dag_label!(format!("L{layer_idx}.attn.qkv_proj")),
            &layer.attention.qkv_proj,
            &bufs.normed,
            qkv_out,
        );
        dag.split_qkv(
            dag_label!(format!("L{layer_idx}.attn.split_qkv")),
            qkv_out,
            &mut bufs.q,
            &mut bufs.k,
            &mut bufs.v,
        )?;
    } else {
        // The split path is the numerical baseline retained by #75.
        dag.gemm_rows::<QDim>(
            dag_label!(format!("L{layer_idx}.attn.q_proj")),
            &layer.attention.qkv_proj,
            0,
            q_dim,
            &bufs.normed,
            &mut bufs.q,
        );
        dag.gemm_rows::<KvDim>(
            dag_label!(format!("L{layer_idx}.attn.k_proj")),
            &layer.attention.qkv_proj,
            q_dim,
            kv_dim,
            &bufs.normed,
            &mut bufs.k,
        );
        dag.gemm_rows::<KvDim>(
            dag_label!(format!("L{layer_idx}.attn.v_proj")),
            &layer.attention.qkv_proj,
            q_dim + kv_dim,
            kv_dim,
            &bufs.normed,
            &mut bufs.v,
        );
    }
    self.apply_decode_lora_projection_group3(
        layer_idx,
        LoraProjectionKind::Q,
        LoraProjectionKind::K,
        LoraProjectionKind::V,
        use_lora,
        &bufs.normed,
        &mut bufs.q,
        &mut bufs.k,
        &mut bufs.v,
        &bufs.lora_token_slots_d,
    )?;

    // QK norm + RoPE (batched, per-request positions)
    dag.qk_norm_rope(
        dag_label!(format!("L{layer_idx}.attn.qk_norm_rope")),
        &mut bufs.q,
        &mut bufs.k,
        &layer.attention.q_norm,
        &layer.attention.k_norm,
        &bufs.positions_d,
    )?;

    // KV append + paged attention decode (FlashInfer, batched)
    dag.paged_decode_attention(
        dag_label!(format!("L{layer_idx}.attn.paged_decode")),
        layer_idx,
        bufs,
    )?;

    // O projection (GEMM)
    dag.o_proj(
        dag_label!(format!("L{layer_idx}.attn.o_proj")),
        &layer.attention.o_proj,
        &bufs.attn_out,
        &mut bufs.attn_proj,
    );
    self.apply_decode_lora_projection(
        layer_idx,
        LoraProjectionKind::O,
        use_lora,
        &bufs.attn_out,
        &mut bufs.attn_proj,
        0,
        &bufs.lora_token_slots_d,
    )?;
    dag.all_reduce_hidden(
        dag_label!(format!("L{layer_idx}.attn.all_reduce")),
        &mut bufs.attn_proj,
    )?;

    // Residual + LayerNorm
    dag.fused_add_rms_norm(
        dag_label!(format!("L{layer_idx}.attn.fused_add_rms_norm")),
        &mut bufs.hidden,
        &bufs.attn_proj,
        &layer.post_attention_layernorm,
        &mut bufs.normed,
    )?;

    dag.mlp_gate_proj(
        dag_label!(format!("L{layer_idx}.mlp.gate_proj")),
        &layer.mlp.gate_up_proj,
        &bufs.normed,
        &mut bufs.gate_out,
    );
    dag.mlp_up_proj(
        dag_label!(format!("L{layer_idx}.mlp.up_proj")),
        &layer.mlp.gate_up_proj,
        &bufs.normed,
        &mut bufs.up_out,
    );
    self.apply_decode_lora_projection_group2(
        layer_idx,
        LoraProjectionKind::Gate,
        LoraProjectionKind::Up,
        use_lora,
        &bufs.normed,
        &mut bufs.gate_out,
        &mut bufs.up_out,
        &bufs.lora_token_slots_d,
    )?;
    dag.silu_mul_split(
        dag_label!(format!("L{layer_idx}.mlp.silu_mul")),
        &bufs.gate_out,
        &bufs.up_out,
        &mut bufs.mlp_act,

